def handle(app, svc):
    resp = svc.apply(app)
    # API v2: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    # Fall back to v1 shape if the partner has not migrated.
    if isinstance(resp, dict) and "result" in resp and isinstance(resp["result"], dict):
        outcome = resp["result"].get("outcome")
        credit_limit = resp["result"].get("credit_limit", 0)
    else:
        outcome = resp.get("decision")
        credit_limit = resp.get("limit", 0)

    # Network referral rule: self_employed with requested_limit > 4000
    # must go to manual review instead of being issued. A decline stays a decline.
    requested_limit = app.get("requested_limit", 0)
    forced_review = (
        app.get("employment") == "self_employed"
        and requested_limit > 4000
    )

    if outcome == "approved":
        if forced_review:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": int(credit_limit or 0)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review (v2) or refer (v1): queue for review, do not decline
    return {"action": "queue_review", "limit": 0}

